import pytest


def fact(n: int) -> int:
    """Return n! for a non-negative integer n. fact(0) is 1."""
    if n < 0:
        raise ValueError("fact is undefined for negative n")
    result = 1
    for i in range(2, n + 1):
        result *= i
    return result


def test_fact_zero() -> None:
    assert fact(0) == 1


def test_fact_one() -> None:
    assert fact(1) == 1


def test_fact_small() -> None:
    assert fact(5) == 120


def test_fact_ten() -> None:
    assert fact(10) == 3628800


def test_fact_returns_int() -> None:
    assert isinstance(fact(6), int)
